# Run with the one-click launcher, or shiny::runApp("STA304 Website-2026").
needed <- c("shiny", "plotly", "DT")
missing <- needed[!vapply(needed, requireNamespace, logical(1), quietly = TRUE)]
if (length(missing)) stop(paste("Install missing packages first:", paste(missing, collapse = ", "), "(see install_packages.R)."))
library(shiny)
source("R/analysis.R", local = TRUE)
source("R/plots.R", local = TRUE)
source("R/server.R", local = TRUE)
analysis_data <- read_analysis_data()

ui <- fluidPage(title = "Sleep before the exam | STA304", lang = "en",
  tags$head(tags$meta(name = "viewport", content = "width=device-width, initial-scale=1"),
    tags$link(rel = "stylesheet", type = "text/css", href = "styles.css")),
  tags$a(class = "skip-link", href = "#analysis", "Skip to analysis"),
  tags$main(class = "app-shell",
    tags$header(class = "page-header-custom",
      div(div(class = "eyebrow", "STA304  /  GROUP NEQUALNP"), h1("Sleep, before the exam."),
        p(class = "subtitle", "Explore reported sleep and study habits around students' most recent assessment.")),
      div(class = "project-badge", span(class = "status-dot"), "85 survey responses")),
    div(class = "requirement-notice", role = "note",
      strong("About this sample."),
      span(" These 85 responses are self-reported and participation was voluntary. Use the filters to explore this sample; the results may not represent the entire class.")),
    div(class = "workspace",
      tags$aside(class = "filter-panel", `aria-label` = "Filters applied to all analysis views",
        div(class = "eyebrow", "THE SAMPLE"), h2("Choose a subgroup"),
        p(class = "muted", "Filters update all plots, statistics, explanations and response rows."),
        selectInput("assessment", "Assessment type", c("All assessments" = "all", "Test / midterm" = "0", "Final examination" = "1"), selectize = FALSE),
        selectInput("recency", "When was the assessment?", c("Any time" = "all", setNames(as.character(1:4), RECENCY_LABELS)), selectize = FALSE),
        selectInput("other_exams", "Other assessments that week", c("Any number" = "all", "None" = "0", "1" = "1", "2" = "2", "3" = "3", "4" = "4", "5 or more" = "5"), selectize = FALSE),
        actionButton("reset", "Reset filters", class = "reset-button"),
        div(class = "filter-count", textOutput("filter_count")),
        hr(), div(class = "eyebrow", "DISPLAY"),
        selectInput("palette", "Plot colours", c("Teal and blue" = "teal", "Blue and orange" = "blue", "Purple and green" = "purple", "Greyscale" = "mono"), selectize = FALSE),
        selectInput("axis_view", "Axis range", c("Fit observed values" = "auto", "Full measurement range" = "full"), selectize = FALSE),
        p(class = "muted", "Use the plot toolbar to zoom, pan or download a figure. Changing tabs chooses which output is visible."),
        div(class = "sidebar-note", strong("One response, one student"),
          p("The cleaned dataset contains 85 responses. One older duplicate was removed. Responses are self-reported and participation was voluntary."))),
      div(class = "analysis-area", id = "analysis",
        div(class = "metric-grid",
          div(class = "metric-card", span(class = "metric-label", "RESPONSES IN VIEW"), textOutput("subset_count"), span(class = "metric-foot", "of 85 cleaned responses")),
          div(class = "metric-card", span(class = "metric-label", "MEAN EXAM-WEEK SLEEP"), textOutput("exam_mean"), span(class = "metric-foot", "hours per night")),
          div(class = "metric-card", span(class = "metric-label", "CHANGE FROM A TYPICAL WEEK"), textOutput("mean_change"), span(class = "metric-foot", "exam week minus typical week"))),
        tabsetPanel(id = "view", type = "tabs",
          tabPanel("Distribution", value = "distribution",
            tags$section(class = "plot-card", h2("How much do students report?"),
              div(class = "control-grid", selectInput("measure", "Measure to plot", NUMERIC_MEASURES, selectize = FALSE),
                sliderInput("bins", "Histogram detail (target bins)", min = 5, max = 25, value = 12, step = 1)),
              plotly::plotlyOutput("distribution_plot", height = "420px"),
              div(class = "interpretation", strong("Reading this plot"), textOutput("distribution_interpretation")))),
          tabPanel("Paired sleep", value = "paired",
            tags$section(class = "plot-card", h2("How does sleep change for the same student?"),
              selectInput("comparison", "Periods to compare", c("Typical week vs exam week" = "typical_exam", "Night before vs night after" = "before_after"), selectize = FALSE),
              plotly::plotlyOutput("comparison_plot", height = "420px"),
              div(class = "interpretation", strong("Reading this plot"), textOutput("comparison_interpretation")),
              h3("Paired estimate and sensitivity check"), textOutput("paired_inference"))),
          tabPanel("Study and sleep", value = "association",
            tags$section(class = "plot-card", h2("Is study time associated with sleep?"),
              checkboxInput("show_fit", "Show fitted line and conventional confidence band", TRUE),
              plotly::plotlyOutput("study_plot", height = "420px"),
              div(class = "interpretation", strong("Reading this plot"), textOutput("study_interpretation")))),
          tabPanel("Statistics", value = "statistics",
            tags$section(class = "table-card", h2("Summary of the selected responses"),
              p(class = "muted", "SD describes spread; IQR uses R's type-7 quartiles. A count of 5 means five or more. Estimated recency uses range midpoints, with an assumed 31-60-day upper category."),
              DT::DTOutput("quantitative"), h3("Mean exam-week sleep"), textOutput("mean_inference"),
              h3("Category counts"), p(class = "muted", "Percentages use the selected subgroup as the denominator."), DT::DTOutput("categorical"),
              p(class = "caveat", "All tests are two-sided and exploratory, without adjustment for repeated subgroup comparisons. Small groups can produce unstable estimates. Confidence intervals and p-values depend on sampling and model assumptions."))),
          tabPanel("Diagnostics", value = "diagnostics",
            tags$section(class = "plot-card", h2("Check assumptions before interpreting a test"),
              selectInput("diagnostic", "Diagnostic to show", c("Paired differences: normal Q-Q plot" = "paired_qq", "Study-sleep regression: residuals vs fitted" = "residuals"), selectize = FALSE),
              plotly::plotlyOutput("diagnostic_plot", height = "400px"),
              div(class = "interpretation", textOutput("diagnostic_interpretation")))),
          tabPanel("Responses", value = "responses",
            tags$section(class = "table-card", h2("Look through the responses"),
              p(class = "muted", "Click a heading to sort or search within the selected subgroup. Table search only narrows the table; it does not filter the plots."),
              DT::DTOutput("responses"), p(class = "table-note", "Response labels R001-R085 are local row labels. Original student IDs, names, emails and timestamps are excluded."))),
          tabPanel("About", value = "about",
            tags$section(class = "table-card about-copy", h2("About this study"),
              p("Group NequalNp studied nightly sleep among Fall 2026 STA304H5 students at the University of Toronto Mississauga who had completed at least one midterm or final examination before responding."),
              h3("How the data were collected"),
              p("The questionnaire was shared through Piazza. Participation was voluntary, and responses were collected from October 5 to 11, 2026. The original 86 submissions contained one duplicated course-specific ID; the later complete submission was retained, leaving 85 responses."),
              p("The revised proposal describes an ideal simple random sample. The available survey responses were collected voluntarily, so this analysis does not claim that a simple random sample was achieved."),
              h3("What the measures mean"),
              p("Weekly sleep averages were reported directly, not calculated from seven nightly diary entries. Study hours refer to studying for the most recent exam over the preceding seven days. Other assessments are top-coded at five or more."),
              p("Exam recency retains its original range category for filtering. A separate estimated-days field implements range midpoints: 0-7 becomes 3.5, 8-14 becomes 11, and 15-30 becomes 22.5. For more than 30 days, we assume a 31-60-day interval and assign 45.5 days. This last value is an analyst assumption, not an observed exam date. It is not used as a regression predictor."),
              h3("Limits of the evidence"),
              p("Recall error, unusual but unverified values, voluntary response bias and unmeasured confounders limit the conclusions. Some reported exams were more than 30 days earlier, and exact exam dates were not collected, so Fall 2026 eligibility cannot be independently confirmed. No respondents are removed solely because they are outliers."),
              p("The original survey did not collect demographic variables such as age or gender. Subgroups shown here describe assessments and workload, using only fields in the cleaned survey data."),
              h3("Reproducibility"),
              p("All views use the same cleaned response rows as the group EDA report. Bootstrap intervals use 10,000 resamples, seeds 3042026 and 3042027. Regression uses original measurements without jitter; HC3 intervals allow unequal error variance. The website distribution display can use different bin widths from the fixed EDA figures without changing any estimates.")))),
        p(class = "caveat", "These are exploratory patterns in a voluntary, self-reported sample. They do not show that exams or studying caused a change in sleep."))),
    tags$footer(class = "app-footer", span("STA304H5F - Group NequalNp"), span("Cleaned survey / EDA / documented recency estimates"))))
shinyApp(ui = ui, server = make_server(analysis_data))
